const REFERENCE_SHEET='https://docs.google.com/spreadsheets/u/1/d/17cNu8hxqJKqkkPnhDlIuJY-IT6ps7kTNCd3BEz0Bvqs/pubhtml?pli=1';
function siteReviewNote(s){const r=SITE_REVIEW.find(r=>r.site===s.site&&r.class===s.class);return r?`<div class="notice">${r.structuralCount?'Reference disagreement: '+r.structuralCount+' wave, trigger, quantity or loot fields need review.':'Wave names, NPC groups, quantities, trigger-group flags and base loot match the comparison sheet.'} ${r.statCount} DPS/EHP fields differ. This comparison is not current-game certification. <a href="#audit">Read the site review →</a></div>`:'';}
function operatingRules(){return `<div class="grid two"><section class="panel"><div class="eyebrow">C5 / C6 · ESCALATION RULES</div><h2>Watch the beacon.</h2><p>CCP’s November 2024 rules require a capital within 100 km to keep the escalation beacon present. Attacking the trigger structure without that beacon produces the weaker Recon variant instead of the Response variant.</p><p>Avengers spawn once per site while the beacon exists, rather than once for every capital group. In data/relic sites, a capital approaching within 100 km creates the beacon once. Losing it cannot be undone by repeatedly bringing capitals back.</p><p>The old spreadsheet’s carrier/dread/FAX wave stack is historical. Unsecured Core Backup Array was separately corrected to four Avengers in December 2024.</p></section><section class="panel"><div class="eyebrow">CHANGES AFTER THE SHEET</div><h2>Rewards and encounters changed.</h2><p>CCP’s September 2025 update raised Avenger loot to 50 million ISK each, changed C2 anomaly warp-in/spawn positions and diversified Drifter target selection. Do not rely on the old sheet’s travel distances or predictable logistics aggro.</p><p>Rampant Drone Fabricator sites returned to C1–C6 in July 2026 with ship-based Rampancy and up to 100 waves. They are outside this 48-site Sleeper archive.</p></section></div>`;}
function audit(){
 $('#app').innerHTML=intro('OPERATIONS / REFERENCE REVIEW','Know what is confirmed.','48 saved C1–C6 combat, data and relic records compared on 2 November 2026.')+`<section class="panel"><h2>34 structural matches. 14 disagreements.</h2><p>The supplied reference is version 1.19, last listed update 19 November 2020. All 48 sites were matched by class and name, including the Sanctuary naming variation. The comparison checks wave labels, NPC group names, quantities, trigger-group flags, base blue loot and DPS/EHP values. It found 447 DPS/EHP field differences.</p><p>Differences are shown below, not silently overwritten: some may be old spreadsheet data, newer NPC stats, optional spawns or rounding. Scram/web/neut values, spawn distances, gas/ore encounters, ship fits and every live-game rule are not fully validated by this check. A match to a 2020 sheet does not prove present-day accuracy.</p></section><div class="sectionhead"><h2>Before running a site</h2></div><section class="panel"><ol><li>Confirm the site name and wormhole class. Read any disagreement below before relying on its trigger marker.</li><li>Check the incoming wave, capacitor pressure and tackle. Choose your fit for your skills and system effect; this archive is not a fitting simulation.</li><li>Handle non-trigger groups first when controlling wave overlap. Trigger-on-attack conditions differ from kill triggers; check drones before firing.</li><li>For C3 Unsecured Frontier Receiver, attacking the Wave 3 Sleepless Defender can start Wave 4. Keep drones passive if you are holding that trigger.</li><li>For C5/C6, check the escalation beacon and the Recon/Response conditions before attacking the structure.</li></ol></section>${operatingRules()}<div class="sectionhead"><h2>Site-by-site comparison</h2><span>EXPAND A RECORD</span></div>`+SITE_REVIEW.map(r=>`<details><summary>${esc(r.class+' · '+r.site)}<small>${r.structuralCount?r.structuralCount+' structural / loot differences':'Structure and loot match'} · ${r.statCount} stat differences</small></summary><div class="inside"><p>Spreadsheet tab ${esc(r.class)}, site heading row ${esc(r.sheetRow)}. Blank/false trigger values mean that source does not mark that group as a trigger. An “x” is the sheet’s trigger flag. Trigger-on-attack timing was reviewed separately for Receiver.</p>${table(r.differences,[['Wave','wave'],['NPC','npc'],['Field','field'],['Website','website',d=>esc(String(d.website??'not listed'))],['Spreadsheet','sheet',d=>esc(String(d.sheet??'not listed'))],['Sheet row','sheetRow']])}</div></details>`).join('');
}
